// Round-robin against first-come-first-served, for every printer speed.
const spool = nb.get('spool');
if (!spool) return 'Run the second Lua cell first.';

function finishTicks(jobs, perTick, roundRobin) {
  const queue = jobs.map(j => ({ name: j.name, pages: j.pages }));
  const done = {};
  let tick = 0;
  while (queue.length) {
    tick++;
    const job = queue.shift();
    job.pages -= Math.min(perTick, job.pages);
    if (job.pages === 0) done[job.name] = tick;
    else if (roundRobin) queue.push(job);    // to the back
    else queue.unshift(job);                 // keep printing it
  }
  return done;
}
const mean = d => Object.values(d).reduce((a, b) => a + b, 0) / Object.keys(d).length;

// The Lua run should match this round-robin exactly.
const mine = finishTicks(spool.jobs, spool.pagesPerTick, true);
const agrees = spool.finished.every(d => mine[d.name] === d.tick);
console.log('Lua round-robin at ' + spool.pagesPerTick + ' pages per tick matches: ' + agrees);

const rr = mine, fcfs = finishTicks(spool.jobs, spool.pagesPerTick, false);
console.log('\njob           pages  round-robin  first-come');
for (const j of spool.jobs) {
  console.log(j.name.padEnd(13) + String(j.pages).padStart(6) + String(rr[j.name]).padStart(13) + String(fcfs[j.name]).padStart(12));
}
console.log('average finish tick: round-robin ' + mean(rr).toFixed(2) + ', first-come ' + mean(fcfs).toFixed(2));

const rows = [];
for (let speed = 1; speed <= 12; speed++) {
  rows.push({ speed, finish: mean(finishTicks(spool.jobs, speed, true)), policy: 'round-robin' });
  rows.push({ speed, finish: mean(finishTicks(spool.jobs, speed, false)), policy: 'first-come, first-served' });
}
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Average finish tick of the four jobs',
  data: { values: rows },
  mark: { type: 'line', point: true },
  encoding: {
    x: { field: 'speed', type: 'quantitative', title: 'pages printed per tick' },
    y: { field: 'finish', type: 'quantitative', title: 'average finish tick' },
    color: { field: 'policy', type: 'nominal', title: null },
  },
};
